/**
 * Generates src/generated/stageFieldMap.ts from stages.ts + juteBags.ts.
 *
 * Run `npm run gen` to regenerate, `npm run gen:check` in CI to fail on drift. The generated file
 * is committed so the backend can import it without a build step; `--check` is what stops it
 * going stale. Adding a field to stages.ts and forgetting the migration is caught separately by
 * tests/stageMap.schema.test.ts, which asserts every (model, col) exists in the Prisma DMMF.
 */
import { writeFileSync, readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { stages, rejectStage } from "../src/data/stages.js";
import { juteLedgers } from "../src/data/juteBags.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const OUT = join(HERE, "..", "src", "generated", "stageFieldMap.ts");

/** stageId -> Prisma model + cardinality. Declared, because the model name is a schema decision. */
const STAGE_MODELS: Record<string, { model: string; relation: string; cardinality: "one" | "many" }> = {
  "n-delplan": { model: "StageDeliveryPlan", relation: "delplan", cardinality: "one" },
  "n-gate": { model: "StageGateEntry", relation: "gate", cardinality: "one" },
  "n-verify": { model: "StageVerifyDocs", relation: "verify", cardinality: "one" },
  "n-qfs": { model: "StageQualityQfs", relation: "qfs", cardinality: "one" },
  "n-gross": { model: "StageGrossWeight", relation: "gross", cardinality: "one" },
  "n-lot": { model: "StageLotAssignment", relation: "lot", cardinality: "one" },
  "n-bin": { model: "StageBinAllocation", relation: "bin", cardinality: "one" },
  "n-unload": { model: "StageUnload", relation: "unload", cardinality: "one" },
  "n-tare": { model: "StageTareWeight", relation: "tare", cardinality: "one" },
  "n-netwt": { model: "StageNetWeight", relation: "netwt", cardinality: "one" },
  "n-grn": { model: "StageGrn", relation: "grn", cardinality: "one" },
  "n-stock": { model: "StageStockUpdate", relation: "stock", cardinality: "one" },
  "n-drying": { model: "StageDryingDecision", relation: "drying", cardinality: "one" },
  // 1:N. ReceiptRecord.stageData is structurally 1:1 (no row index), so the assembler projects
  // only the most recent row for these two; the full set is served by /api/receipts/:id/activities.
  "n-otheract": { model: "OtherActivity", relation: "otherActivities", cardinality: "many" },
  "n-ledger": { model: "ActivityLedgerEntry", relation: "activityLedger", cardinality: "many" },
  "n-xferdec": { model: "StageTransferDecision", relation: "xferdec", cardinality: "one" },
  "n-reject": { model: "StageRejection", relation: "reject", cardinality: "one" },
};

const LEDGER_MODELS: Record<string, string> = {
  "warehouse-stock": "JuteWarehouseMovement",
  "supplier-movement": "JuteSupplierMovement",
  "factory-production-tracking": "JuteProductionMovement",
  "warehouse-to-warehouse-movement": "JuteWarehouseTransferReceipt",
};

const all = [...stages, rejectStage];
const q = (s: string) => JSON.stringify(s);

// Guard the invariants the whole design rests on, at generation time.
const seenPairs = new Set<string>();
for (const s of all) {
  const spec = STAGE_MODELS[s.id];
  if (!spec) throw new Error(`stages.ts has "${s.id}" but STAGE_MODELS does not — add a model.`);
  const cols = new Set<string>();
  for (const f of s.fields) {
    if (!f.col) throw new Error(`${s.id} / "${f.n}" has no col`);
    if (Buffer.byteLength(f.col) > 63) throw new Error(`${s.id}.${f.col} exceeds Postgres' 63-byte identifier limit`);
    if (cols.has(f.col)) throw new Error(`${s.id} reuses col "${f.col}" — cols must be unique per stage`);
    cols.add(f.col);
    const pair = `${s.id}\u0000${f.n}`;
    if (seenPairs.has(pair)) throw new Error(`duplicate (stageId,label): ${pair}`);
    seenPairs.add(pair);
  }
}
for (const id of Object.keys(STAGE_MODELS)) {
  if (!all.some((s) => s.id === id)) throw new Error(`STAGE_MODELS has "${id}" but stages.ts does not.`);
}

const fieldCount = all.reduce((n, s) => n + s.fields.length, 0);

const body = `// GENERATED by scripts/gen-stage-map.ts — do not edit. Run \`npm run gen\` after changing
// stages.ts or juteBags.ts; \`npm run gen:check\` fails CI if this file is stale.
//
// ${all.length} stage records, ${fieldCount} (stageId, label) pairs.

export interface StageFieldEntry { label: string; col: string }

export interface StageTableSpec {
  stageId: string;
  model: string;
  /** Receipt relation field name, for Prisma include/select. */
  relation: string;
  /** "one": 1:1 with Receipt, PK = receiptId. "many": 1:N entity, assembler projects latest row. */
  cardinality: "one" | "many";
  kind: string;
  fields: StageFieldEntry[];
}

export const STAGE_FIELD_MAP: Record<string, StageTableSpec> = {
${all
  .map((s) => {
    const m = STAGE_MODELS[s.id];
    const fields = s.fields.map((f) => `      { label: ${q(f.n)}, col: ${q(f.col)} },`).join("\n");
    return `  ${q(s.id)}: {
    stageId: ${q(s.id)},
    model: ${q(m.model)},
    relation: ${q(m.relation)},
    cardinality: ${q(m.cardinality)},
    kind: ${q(s.kind)},
    fields: [
${fields}
    ],
  },`;
  })
  .join("\n")}
};

export const STAGE_IDS: string[] = [${all.map((s) => q(s.id)).join(", ")}];

/** label -> col for one stage. Throws on an unknown label so a typo can't silently no-op a write. */
export function colFor(stageId: string, label: string): string {
  const spec = STAGE_FIELD_MAP[stageId];
  if (!spec) throw new Error(\`Unknown stage "\${stageId}"\`);
  const f = spec.fields.find((x) => x.label === label);
  if (!f) throw new Error(\`Unknown field "\${label}" on stage "\${stageId}"\`);
  return f.col;
}

export interface LedgerColumnEntry { label: string; col: string; real: boolean }

export const LEDGER_COLUMN_MAP: Record<string, { ledgerId: string; model: string; columns: LedgerColumnEntry[] }> = {
${juteLedgers
  .map((l) => {
    const cols = l.columns
      .map((c) => `      { label: ${q(c.label)}, col: ${q(c.col)}, real: ${c.real} },`)
      .join("\n");
    return `  ${q(l.id)}: {
    ledgerId: ${q(l.id)},
    model: ${q(LEDGER_MODELS[l.id])},
    columns: [
${cols}
    ],
  },`;
  })
  .join("\n")}
};

export const LEDGER_IDS: string[] = [${juteLedgers.map((l) => q(l.id)).join(", ")}];
`;

const check = process.argv.includes("--check");
if (check) {
  const current = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
  if (current !== body) {
    console.error("stageFieldMap.ts is STALE — run `npm run gen` and commit the result.");
    process.exit(1);
  }
  console.log(`stageFieldMap.ts up to date (${all.length} stages, ${fieldCount} fields).`);
} else {
  writeFileSync(OUT, body);
  console.log(`Wrote ${OUT} — ${all.length} stages, ${fieldCount} fields, ${juteLedgers.length} ledgers.`);
}
